27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
69	    private Set<Pet> pets;
70	
71	    public String getAddress() {
72	        return this.address;
73	    }
74	
75	    public void setAddress(String address) {
76	        this.address = address;
77	    }
78	
79	    public String getCity() {
80	        return this.city;
81	    }
82	
83	    public void setCity(String city) {
84	        this.city = city;
85	    }
86	
87	    public String getTelephone() {
88	        return this.telephone;
89	    }
90	
91	    public void setTelephone(String telephone) {
92	        this.telephone = telephone;
93	    }
94	
95	    public String getEmail() {
96	        return this.email;
97	    }
98	
99	    public void setEmail(String email) {
100	        this.email = email;
101	    }
102	
103	    public LocalDate getRegistrationDate() {
104	        return this.registrationDate;
105	    }
106	
107	    public void setRegistrationDate(LocalDate registrationDate) {
108	        this.registrationDate = registrationDate;
109	    }
110	
111	    public String getCustomerCode() {
112	        return this.customerCode;
113	    }
114	
115	    public void setCustomerCode(String customerCode) {
116	        this.customerCode = customerCode;
117	    }
118	
119	    public String getHouseholdId() {
120	        return this.householdId;
121	    }
122	
123	    public void setHouseholdId(String householdId) {
124	        this.householdId = householdId;
125	    }
126	
127	    public Integer getNamesakeCount() {
128	        return this.namesakeCount;
129	    }
130	
131	    public void setNamesakeCount(Integer namesakeCount) {
132	        this.namesakeCount = namesakeCount;
133	    }
134	
135	    /**
136	     * Stamp the owner's registration date with the server's current date on first
137	     * persist when none was supplied, so the default applies on every create path.
138	     */
139	    @PrePersist
140	    protected void onCreate() {
141	        if (this.registrationDate == null) {
142	            this.registrationDate = LocalDate.now();
143	        }
144	    }
145	
146	    protected Set<Pet> getPetsInternal() {
147	        if (this.pets == null) {
148	            this.pets = new HashSet<>();
149	        }
150	        return this.pets;
151	    }
152	
153	    protected void setPetsInternal(Set<Pet> pets) {
154	        this.pets = pets;
155	    }
156	
157	    public List<Pet> getPets() {
158	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
159	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
160	        return Collections.unmodifiableList(sortedPets);
161	    }
162	
163	    public void setPets(List<Pet> pets) {
164	        this.pets = new HashSet<>(pets);
165	    }
166	
167	    public void addPet(Pet pet) {
168	        getPetsInternal().add(pet);
169	        pet.setOwner(this);
170	    }
171	
172	    /**
173	     * Return the Pet with the given name, or null if none found for this Owner.
174	     *
175	     * @param name to test
176	     * @return true if pet name is already in use
177	     */
178	    public Pet getPet(String name) {
179	        return getPet(name, false);
180	    }
181	
182	    /**
183	     * Return the Pet with the given name, or null if none found for this Owner.
184	     *
185	     * @param name to test
186	     * @return true if pet name is already in use
187	     */
188	    public Pet getPet(String name, boolean ignoreNew) {
189	        name = name.toLowerCase();
190	        for (Pet pet : getPetsInternal()) {
191	            if (!ignoreNew || !pet.isNew()) {
192	                String compName = pet.getName();
193	                compName = compName.toLowerCase();
194	                if (compName.equals(name)) {
195	                    return pet;
196	                }
197	            }
198	        }
199	        return null;
200	    }
201	
202	    public Pet getPet(Integer petId) {
203	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
204	    }
205	
206	    @Override
207	    public String toString() {
208	        return new ToStringCreator(this)
209	
210	            .append("id", this.getId())
211	            .append("new", this.isNew())
212	            .append("lastName", this.getLastName())
213	            .append("firstName", this.getFirstName())
214	            .append("address", this.address)
215	            .append("city", this.city)
216	            .append("telephone", this.telephone)
217	            .toString();
218	    }
219	}
