16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.dao.DataAccessException;
19	import org.springframework.dao.EmptyResultDataAccessException;
20	import org.springframework.data.domain.Page;
21	import org.springframework.data.domain.Pageable;
22	import org.springframework.orm.ObjectRetrievalFailureException;
