28	import org.springframework.stereotype.Service;
29	import org.springframework.transaction.annotation.Transactional;
30	
31	import java.nio.charset.StandardCharsets;
32	import java.security.MessageDigest;
33	import java.security.NoSuchAlgorithmException;
34	import java.util.Collection;
35	import java.util.List;
36	import java.util.Locale;
37	import java.util.Set;
38	import java.util.function.Supplier;
39	
40	/**
41	 * Mostly used as a facade for all Petclinic controllers
42	 * Also a placeholder for @Transactional and @Cacheable annotations
43	 *
44	 * @author Michael Isvy
45	 * @author Vitaliy Fedoriv
46	 */
47	@Service
48	public class ClinicServiceImpl implements ClinicService {
49	
50	    private final PetRepository petRepository;
51	    private final VetRepository vetRepository;
52	    private final OwnerRepository ownerRepository;
53	    private final VisitRepository visitRepository;
54	    private final SpecialtyRepository specialtyRepository;
55	    private final PetTypeRepository petTypeRepository;
56	
57	    public ClinicServiceImpl(
58	        PetRepository petRepository,
59	        VetRepository vetRepository,
60	        OwnerRepository ownerRepository,
61	        VisitRepository visitRepository,
62	        SpecialtyRepository specialtyRepository,
63	        PetTypeRepository petTypeRepository) {
64	        this.petRepository = petRepository;
65	        this.vetRepository = vetRepository;
66	        this.ownerRepository = ownerRepository;
67	        this.visitRepository = visitRepository;
68	        this.specialtyRepository = specialtyRepository;
69	        this.petTypeRepository = petTypeRepository;
70	    }
71	
72	    @Override
73	    @Transactional(readOnly = true)
74	    public Collection<Pet> findAllPets() throws DataAccessException {
75	        return petRepository.findAll();
76	    }
77	
78	    @Override
79	    @Transactional(readOnly = true)
80	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
81	        return petRepository.findAll(pageable);
82	    }
83	
84	    @Override
85	    @Transactional
86	    public void deletePet(Pet pet) throws DataAccessException {
87	        petRepository.delete(pet);
88	    }
89	
90	    @Override
91	    @Transactional(readOnly = true)
92	    public Visit findVisitById(int visitId) throws DataAccessException {
93	        return findEntityById(() -> visitRepository.findById(visitId));
94	    }
95	
96	    @Override
97	    @Transactional(readOnly = true)
98	    public Collection<Visit> findAllVisits() throws DataAccessException {
99	        return visitRepository.findAll();
100	    }
101	
102	    @Override
103	    @Transactional
104	    public void deleteVisit(Visit visit) throws DataAccessException {
105	        visitRepository.delete(visit);
106	    }
107	
108	    @Override
109	    @Transactional(readOnly = true)
110	    public Vet findVetById(int id) throws DataAccessException {
111	        return findEntityById(() -> vetRepository.findById(id));
112	    }
113	
114	    @Override
115	    @Transactional(readOnly = true)
116	    public Collection<Vet> findAllVets() throws DataAccessException {
117	        return vetRepository.findAll();
118	    }
119	
120	    @Override
121	    @Transactional
122	    public void saveVet(Vet vet) throws DataAccessException {
123	        vetRepository.save(vet);
124	    }
125	
126	    @Override
127	    @Transactional
128	    public void deleteVet(Vet vet) throws DataAccessException {
129	        vetRepository.delete(vet);
130	    }
131	
132	    @Override
133	    @Transactional(readOnly = true)
134	    public Collection<Owner> findAllOwners() throws DataAccessException {
135	        return ownerRepository.findAll();
136	    }
137	
138	    @Override
139	    @Transactional(readOnly = true)
140	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
141	        if (lastName != null) {
142	            return ownerRepository.findByLastName(lastName, pageable);
143	        }
144	        return ownerRepository.findAll(pageable);
145	    }
146	
147	    @Override
148	    @Transactional
149	    public void deleteOwner(Owner owner) throws DataAccessException {
150	        ownerRepository.delete(owner);
151	    }
152	
153	    @Override
154	    @Transactional(readOnly = true)
155	    public PetType findPetTypeById(int petTypeId) {
156	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
157	    }
158	
159	    @Override
160	    @Transactional(readOnly = true)
161	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
162	        return petTypeRepository.findAll();
163	    }
164	
165	    @Override
166	    @Transactional
167	    public void savePetType(PetType petType) throws DataAccessException {
168	        petTypeRepository.save(petType);
169	    }
170	
171	    @Override
172	    @Transactional
173	    public void deletePetType(PetType petType) throws DataAccessException {
174	        petTypeRepository.delete(petType);
175	    }
176	
177	    @Override
178	    @Transactional(readOnly = true)
179	    public Specialty findSpecialtyById(int specialtyId) {
180	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
181	    }
182	
183	    @Override
184	    @Transactional(readOnly = true)
185	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
186	        return specialtyRepository.findAll();
187	    }
188	
189	    @Override
190	    @Transactional
191	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
192	        specialtyRepository.save(specialty);
193	    }
194	
195	    @Override
196	    @Transactional
197	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
198	        specialtyRepository.delete(specialty);
199	    }
200	
201	    @Override
202	    @Transactional(readOnly = true)
203	    public Collection<PetType> findPetTypes() throws DataAccessException {
204	        return petRepository.findPetTypes();
205	    }
206	
207	    @Override
208	    @Transactional(readOnly = true)
209	    public Owner findOwnerById(int id) throws DataAccessException {
210	        return findEntityById(() -> ownerRepository.findById(id));
211	    }
212	
213	    @Override
214	    @Transactional(readOnly = true)
215	    public Pet findPetById(int id) throws DataAccessException {
216	        return findEntityById(() -> petRepository.findById(id));
217	    }
218	
219	    @Override
220	    @Transactional
221	    public void savePet(Pet pet) throws DataAccessException {
222	        pet.setType(findPetTypeById(pet.getType().getId()));
223	        petRepository.save(pet);
224	    }
225	
226	    @Override
227	    @Transactional
228	    public void saveVisit(Visit visit) throws DataAccessException {
229	        visitRepository.save(visit);
230	
231	    }
232	
233	    @Override
234	    @Transactional(readOnly = true)
235	    public Collection<Vet> findVets() throws DataAccessException {
236	        return vetRepository.findAll();
237	    }
238	
239	    @Override
240	    @Transactional
241	    public void saveOwner(Owner owner) throws DataAccessException {
242	        if (owner.isNew()) {
243	            if (owner.getCustomerCode() == null) {
244	                owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
245	            }
246	            if (owner.getNamesakeCount() == null) {
247	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
248	            }
249	        }
250	        ownerRepository.save(owner);
251	
252	    }
253	
254	    /**
255	     * Count the existing owners (before this create) that share the given first and last name,
256	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
257	     */
258	    private int countNamesakes(String firstName, String lastName) {
259	        if (firstName == null || lastName == null) {
260	            return 0;
261	        }
262	        return (int) ownerRepository.findAll().stream()
263	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
264	                && lastName.equalsIgnoreCase(owner.getLastName()))
265	            .count();
266	    }
267	
268	    /**
269	     * Build a customer code formatted {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the
270	     * upper-cased first three letters of the owner's last name and {@code NNNN} is a global,
271	     * 4-digit zero-padded sequence equal to one more than the current number of owners
272	     * (e.g. {@code 'SMI-0007'}).
273	     */
274	    private String generateCustomerCode(String lastName) {
275	        String name = lastName == null ? "" : lastName;
276	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
277	        long sequence = ownerRepository.findAll().size() + 1L;
278	        return String.format("%s-%04d", last3, sequence);
279	    }
280	
281	    @Override
282	    @Transactional(readOnly = true)
283	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
284	        String normalized = normalizeTelephone(telephone);
285	        if (normalized == null) {
286	            return false;
287	        }
288	        return ownerRepository.findAll().stream()
289	            .map(owner -> normalizeTelephone(owner.getTelephone()))
290	            .anyMatch(normalized::equals);
291	    }
292	
293	    @Override
294	    @Transactional(readOnly = true)
295	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
296	        String normalizedLastName = normalizeHouseholdValue(lastName);
297	        String normalizedAddress = normalizeHouseholdAddress(address);
298	        if (normalizedLastName.isEmpty() || normalizedAddress.isEmpty()) {
299	            return false;
300	        }
301	        return ownerRepository.findAll().stream()
302	            .anyMatch(owner -> normalizedLastName.equals(normalizeHouseholdValue(owner.getLastName()))
303	                && normalizedAddress.equals(normalizeHouseholdAddress(owner.getAddress())));
304	    }
305	
306	    @Override
307	    @Transactional(readOnly = true)
308	    public String householdIdFor(String lastName, String address) throws DataAccessException {
309	        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
310	        try {
311	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
312	            StringBuilder sb = new StringBuilder(32);
313	            for (int i = 0; i < 8; i++) {
314	                sb.append(String.format("%02X", digest[i]));
315	            }
316	            return sb.toString();
317	        } catch (NoSuchAlgorithmException ex) {
318	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
319	        }
320	    }
321	
322	    /**
323	     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
324	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
325	     * spaced but equivalent values compare equal.
326	     */
327	    private static String normalizeHouseholdValue(String value) {
328	        if (value == null) {
329	            return "";
330	        }
331	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
332	    }
333	
334	    /**
335	     * Normalizes an address for household comparison by first applying the canonical address
336	     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
337	     * then the shared household-value normalization, so every address comparison uses the same
338	     * normalized form regardless of how the value was originally supplied.
